<?php
declare(strict_types=1);
namespace KodVadAll\Core;
use PDO;
use RuntimeException;
final class LicenseService
{
 public static function domain():string{$host=strtolower((string)($_SERVER['HTTP_HOST']??'localhost'));$host=preg_replace('/:\d+$/','',$host)??$host;return preg_replace('/^www\./','',$host)??$host;}
 public static function fingerprint():string{$path=KD_STORAGE.'/install.id';if(!is_file($path)){if(file_put_contents($path,bin2hex(random_bytes(32)),LOCK_EX)===false)throw new RuntimeException('Kurulum kimliği oluşturulamadı.');@chmod($path,0600);}return hash('sha256','KodVadAll|'.self::domain().'|'.trim((string)file_get_contents($path)));}
 public static function activationRequest(PDO $db):array{$email=(string)$db->query("SELECT setting_value FROM settings WHERE setting_key='email'")->fetchColumn();return ['product'=>'KodVadAll','domain'=>self::domain(),'machine_fingerprint'=>self::fingerprint(),'version'=>self::version(),'contact_email'=>$email,'requested_at'=>date(DATE_ATOM)];}
 public static function version():string{$path=KD_ROOT.'/VERSION';return is_file($path)?trim((string)file_get_contents($path)):'0.0.0';}
 public static function current(PDO $db):array
 {
  $path=KD_STORAGE.'/license.json';if(!is_file($path))return ['status'=>'unlicensed','message'=>'Henüz lisans etkinleştirilmedi.','payload'=>null];$doc=json_decode((string)file_get_contents($path),true);if(!is_array($doc))return ['status'=>'invalid','message'=>'Lisans dosyası okunamadı.','payload'=>null];$key=(string)$db->query("SELECT setting_value FROM settings WHERE setting_key='license_public_key'")->fetchColumn();if($key===''||!isset($doc['payload'],$doc['signature']))return ['status'=>'invalid','message'=>'Lisans doğrulama anahtarı veya imza eksik.','payload'=>$doc['payload']??null];$json=json_encode($doc['payload'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$signature=base64_decode((string)$doc['signature'],true);$public=openssl_pkey_get_public($key);if($signature===false||$public===false||openssl_verify($json,$signature,$public,OPENSSL_ALGO_SHA256)!==1)return ['status'=>'invalid','message'=>'Lisans imzası doğrulanamadı.','payload'=>$doc['payload']];$p=$doc['payload'];if(($p['product']??'')!=='KodVadAll'||strtolower((string)($p['domain']??''))!==self::domain()||!hash_equals(self::fingerprint(),(string)($p['machine_fingerprint']??'')))return ['status'=>'invalid','message'=>'Lisans farklı bir ürün, alan adı veya kurulum için düzenlenmiş.','payload'=>$p];if(!empty($p['expires_at'])&&strtotime((string)$p['expires_at'])<time())return ['status'=>'expired','message'=>'Lisans süresi dolmuş.','payload'=>$p];return ['status'=>'active','message'=>'Lisans doğrulandı.','payload'=>$p];
 }
 public static function savePublicKey(PDO $db,string $key):void{if(openssl_pkey_get_public($key)===false)throw new RuntimeException('Geçerli bir RSA açık anahtarı girin.');$db->prepare("INSERT INTO settings (setting_key,setting_value,updated_at) VALUES ('license_public_key',?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()")->execute([trim($key)]);}
 public static function activate(PDO $db,string $path):array
 {
  $doc=json_decode((string)file_get_contents($path),true);if(!is_array($doc)||!isset($doc['payload'],$doc['signature']))throw new RuntimeException('Lisans JSON dosyası biçimi geçersiz.');$tmp=KD_STORAGE.'/license-upload-'.bin2hex(random_bytes(4)).'.json';if(file_put_contents($tmp,json_encode($doc,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX)===false)throw new RuntimeException('Lisans dosyası geçici alana yazılamadı.');$target=KD_STORAGE.'/license.json';$old=is_file($target)?file_get_contents($target):null;if(!rename($tmp,$target))throw new RuntimeException('Lisans dosyası güvenli alana taşınamadı.');@chmod($target,0600);$state=self::current($db);if($state['status']!=='active'){if($old!==null)file_put_contents($target,$old,LOCK_EX);else @unlink($target);throw new RuntimeException($state['message']);}$p=$state['payload'];$db->prepare("INSERT INTO license_activations (license_id,customer_name,edition,licensed_domain,machine_fingerprint,issued_at,expires_at,features_json,signature_hash,status,activated_at,created_at) VALUES (?,?,?,?,?,?,?,?,?,'active',NOW(),NOW())")->execute([(string)($p['license_id']??'unknown'),$p['customer']??null,$p['edition']??null,(string)$p['domain'],(string)$p['machine_fingerprint'],$p['issued_at']??null,$p['expires_at']??null,json_encode($p['features']??[]),hash('sha256',(string)$doc['signature'])]);return $p;
 }
 public static function hasFeature(PDO $db,string $feature):bool{$state=self::current($db);return $state['status']==='active'&&in_array($feature,$state['payload']['features']??[],true);}
}
